      if (!res.ok) throw new Error(`AviationWeather TAF ${res.status}`);
      return parseTafResponse(await res.text(), airportByIcao);
    } catch (err) {
      lastErr = err as Error;
      if (attempt < retries) {
        const delay = (attempt + 1) * 2000;
